import itertools

def hamming_distance(s1, s2):
    """Calculates the Hamming distance between two binary strings (represented as tuples or strings)."""
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_strings(n):
    """Generates all 2^n binary strings of length n."""
    return [''.join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]

def calculate_neighborhood(S_L, n, k):
    """Calculates the set C(S_L) of all strings at distance k from S_L."""
    C_SL = set()
    all_strings = generate_strings(n)
    for V in all_strings:
        if hamming_distance(S_L, V) == k:
            C_SL.add(V)
    return frozenset(C_SL)

def analyze_injectivity(n, k):
    """Checks if the mapping S_L -> C(S_L) is injective for given n and k."""
    if n <= 0 or k < 0 or n <= 2 * k:
        return "Invalid parameters (n > 2k required)", {}

    print(f"--- Analyzing n={n}, k={k} ---")

    # Dictionary to store: Neighborhood (frozenset) -> List of S_L that map to it
    neighborhood_map = {}

    all_strings = generate_strings(n)

    for S_L in all_strings:
        C_SL = calculate_neighborhood(S_L, n, k)

        if C_SL not in neighborhood_map:
            neighborhood_map[C_SL] = []

        neighborhood_map[C_SL].append(S_L)

    collisions = {C: list_of_S_L for C, list_of_S_L in neighborhood_map.items() if len(list_of_S_L) > 1}

    if collisions:
        print(f"Found {len(collisions)} collision classes.")
        return "Collision detected", collisions
    else:
        print("Mapping appears injective (no collisions found).")
        return "Injective", {}

